    "image_url": "https://www.giallozafferano.it/images/190-19057/Pasta-Sfoglia_650x433_wm.jpg",
    "source_site": "Giallo Zafferano",
    "source_url": "https://ricette.giallozafferano.it/Pasta-Sfoglia.html",
    "prep_time_min": 80,
    "cook_time_min": 0,
    "total_time_min": 80,
    "servings": 4,
    "difficulty": "difficile",
